import{_ as t,o as a,c as o,a3 as n}from"./chunks/framework.CchDE9cb.js";const i="/capacitylens/assets/projects-page.Cm1AEjr3.jpg",s="/capacitylens/assets/allocation-form.CPQBiRDU.jpg",r="/capacitylens/assets/allocation-open.CO8J-s66.jpg",y=JSON.parse(`{"title":"Projects and allocations","description":"Set up clients and projects, then book a person's time against them by drawing directly on the schedule.","frontmatter":{"title":"Projects and allocations","description":"Set up clients and projects, then book a person's time against them by drawing directly on the schedule."},"headers":[],"relativePath":"guide/projects-and-allocations.md","filePath":"guide/projects-and-allocations.md","lastUpdated":null}`),l={name:"guide/projects-and-allocations.md"};function c(d,e,h,p,g,u){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="projects-and-allocations" tabindex="-1">Projects and allocations <a class="header-anchor" href="#projects-and-allocations" aria-label="Permalink to &quot;Projects and allocations&quot;">​</a></h1><p>Work in CapacityLens hangs off a simple shape: a client owns projects, and a project owns the <a href="/capacitylens/reference/glossary">activities</a> people are actually booked against. This page covers setting that up and creating the <a href="/capacitylens/reference/glossary">allocations</a> that appear as bars on <a href="/capacitylens/guide/the-schedule">the schedule</a>.</p><h2 id="clients-and-projects" tabindex="-1">Clients and projects <a class="header-anchor" href="#clients-and-projects" aria-label="Permalink to &quot;Clients and projects&quot;">​</a></h2><ol><li>Open <strong>Clients</strong>.</li><li>Click <strong>Add client</strong>, then give it a name and a colour.</li><li>Open <strong>Projects</strong>.</li><li>Click <strong>Add project</strong>. Every project belongs to a client, so choose one from the list.</li></ol><p><img src="'+i+'" alt="The Projects page listing projects with their client names and an Add project button"></p><p>Every company starts with one built-in client called <strong>Internal</strong> for non-billable work — general admin, internal meetings, anything that isn&#39;t client work. It can&#39;t be renamed or deleted, and its colour on the schedule is controlled from <a href="/capacitylens/guide/settings">Settings</a>.</p><p>If a client or project name shouldn&#39;t be visible to most of the team — an unannounced prospect, for example — turn on its &quot;use a code name&quot; option when you create or edit it. Everyone below Owner sees a generic code name instead of the real one; only the Owner sees both. See <a href="/capacitylens/getting-started/roles-and-permissions">Roles and permissions</a> for what each role can see.</p><h3 id="activities" tabindex="-1">Activities <a class="header-anchor" href="#activities" aria-label="Permalink to &quot;Activities&quot;">​</a></h3><p>Under <strong>Activities</strong>, an activity is the specific thing a person is booked to do, and it comes in three kinds:</p><ul><li><strong>Project-specific</strong> — belongs to one project.</li><li><strong>Internal</strong> — non-billable work that isn&#39;t tied to a project.</li><li><strong>Cross-project</strong> — work that applies across projects, like general account management.</li></ul><h2 id="create-an-allocation" tabindex="-1">Create an allocation <a class="header-anchor" href="#create-an-allocation" aria-label="Permalink to &quot;Create an allocation&quot;">​</a></h2><p>There are two ways to book a person&#39;s time on the schedule:</p><ol><li>Click the <strong>+</strong> button on their row, which opens the allocation form pre-filled with the visible week.</li><li>Draw it directly: click and drag across the days you want on that person&#39;s row.</li></ol><p><img src="'+s+'" alt="The New allocation form with Project, Activity, Start Date, End Date, Hours / day and Status fields, plus an Add activity button"></p><p>Either way, fill in the project or activity and save. If the activity you need doesn&#39;t exist yet, an &quot;Add activity&quot; option inside the same form can create it on the spot — unless your company has turned that convenience off in <a href="/capacitylens/guide/settings">Settings</a>.</p><h2 id="edit-move-and-remove-allocations" tabindex="-1">Edit, move and remove allocations <a class="header-anchor" href="#edit-move-and-remove-allocations" aria-label="Permalink to &quot;Edit, move and remove allocations&quot;">​</a></h2><ul><li><strong>Move</strong> a bar by dragging it to a different set of days, or drop it on another person&#39;s row to reassign the work.</li><li><strong>Resize</strong> a bar from either edge to change its start or end date.</li><li><strong>Open</strong> a bar to change its status between tentative, confirmed and completed, or to duplicate or delete it. Deleting can be undone from the toolbar, or with Ctrl/Cmd+Z.</li></ul><p><img src="'+r+'" alt="The Edit allocation form for an existing bar, showing its assignee, project, activity, dates and status"></p><h2 id="how-allocation-granularity-works" tabindex="-1">How allocation granularity works <a class="header-anchor" href="#how-allocation-granularity-works" aria-label="Permalink to &quot;How allocation granularity works&quot;">​</a></h2><p>An allocation is a date range plus how much of the day it takes — there&#39;s no hour-by-hour calendar and nothing resembling a timesheet to fill in. How you enter that effort depends on your company&#39;s scheduling mode, set in <a href="/capacitylens/guide/settings">Settings</a>:</p><ul><li><strong>Hours</strong> (the default) — set a start date, an end date and hours per day directly.</li><li><strong>Days</strong> — say how many days of work you need and how many days to spread them over; CapacityLens works out the hours per day for you.</li><li><strong>Blocks</strong> — book someone for a span of days with no hours at all, for work that shouldn&#39;t count toward the utilisation figures.</li></ul><p>Whichever mode you use, CapacityLens is planning capacity, not logging time worked — there&#39;s nothing to submit at the end of the week.</p><p>That&#39;s as fine-grained as scheduling gets — there are no budgets, timesheets or hour-by-hour calendars. <a href="/capacitylens/getting-started/what-is-capacitylens">What is CapacityLens?</a> explains why those lines are drawn where they are.</p><h2 id="what-s-next" tabindex="-1">What&#39;s next <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s next&quot;">​</a></h2><p><a href="/capacitylens/guide/time-off">Time off</a> covers marking someone unavailable, which the allocation form will warn you about if it overlaps a booking.</p>',25)])])}const f=t(l,[["render",c]]);export{y as __pageData,f as default};
